                for (int t = p; t < svN; t++) {
                    bool pkTook = true;
                    int pk = default;
                    try { pk = st.Peek(fz_o[t], fz_h[t], fz_l[t], fz_c[t]); } catch (ArgumentException) { pkTook = false; peekRejects++; }
