            }
            RetCode rc;
            try { rc = c2.CdlonneckImpl(0, svN - 1, fz_o, fz_h, fz_l, fz_c, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITALibFailure) { rc = ((ITALibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.CdlonneckLookback();
