                    RetCode rcS;
                    try { rcS = c2.CdlonneckImpl(Sidx, svN - 1, fz_o, fz_h, fz_l, fz_c, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITALibFailure) { rcS = ((ITALibFailure)_sve).RetCode; }
