        bool allOk = true;
        bool peekAll = true;
        long peekReps = 0;
        long peekRejects = 0;
        bool peekRepAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
