                            Core.KcStream stA = c2.KcOpenInternal(fz_h[..svN], fz_l[..svN], fz_c[..svN], Sidx, optInTimePeriod, optInATRPeriod, optInNbDev);
                            rangeChecked = 1; rangeLegs++; rangeSites |= 4;
