                catch (ArgumentException) { /* expected: output 0 aliases input inLow */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, fz_c, f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inClose */ }
