                catch (ArgumentException) { /* expected: output 1 aliases input inHigh */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, fz_l, f2); fillOk = false; }
