                catch (ArgumentException) { /* expected: output 1 aliases input inClose */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, f1, fz_h); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inHigh */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, f1, fz_l); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inLow */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, f1, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inClose */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, f0, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases output 0 */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, f1, f0); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases output 0 */ }
                try { _ = c2.KdjOpenAndFill(fz_h, fz_l, fz_c, optInFastK_Period, optInSlowK_Period, optInSlowK_MAType, optInSlowD_Period, optInSlowD_MAType, f0, f1, f1); fillOk = false; }
