                        } else { peekRejects++; }
                    }
                    int up = st.Update(fz_c[t]);
                    if (pkTook && (pk != up)) peekAll = false;
                    try { _ = st.Peek(fz_c[t - 1]); } catch (ArgumentException) { peekRejects++; }
