                try { _ = c2.NviOpenAndFill(fz_c, fz_v, fz_v); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 aliases input inVolume */ }
                double[] ovIn = new double[svN + 1];
                Array.Copy(fz_c, ovIn, svN);
