                    for (int bi = 0; bi < nb; bi++) if (f1[bi] != b1[bi]) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f0[bi] != (double)-1.2345678901234e300) fillOk = false;
                    for (int bi = nb; bi < svN; bi++) if (f1[bi] != (int)-987654321) fillOk = false;
                }
