                        try { _ = st.Peek(fz_h[t - 1], fz_l[t - 1], fz_c[t - 1], fz_v[t - 1]); } catch (ArgumentException) { peekRejects++; }
                        double rp = default;
                        try { rp = st.Peek(fz_h[t], fz_l[t], fz_c[t], fz_v[t]); } catch (ArgumentException) { rpTook = false; }
                        if (rpTook) {
                            peekReps++;
