                    try {
                        Core.VwapStream sA = c2.VwapOpen(fz_h[..p0], fz_l[..p0], fz_c[..p0], fz_v[..p0]);
                        int mid = (p0 + svN) / 2;
                        for (int t = p0; t < mid; t++) sA.Update(fz_h[t], fz_l[t], fz_c[t], fz_v[t]);
