                    RetCode rcS;
                    try { rcS = c2.VwapImpl(Sidx, svN - 1, fz_h, fz_l, fz_c, fz_v, out begS, out nbS, b0); }
                    catch (Exception _sve) when (_sve is ITALibFailure) { rcS = ((ITALibFailure)_sve).RetCode; }
