    // ---- ride-along: batch-vs-stream on caller-supplied data ----
    const int RIDE_MAX_BARS = 4096;
    const int RIDE_SEEN_N = 2048;
    static readonly ulong[] rideSeenHash = new ulong[RIDE_SEEN_N];
    static readonly bool[] rideSeenUsed = new bool[RIDE_SEEN_N];
    static readonly int[] rideSeenOpen = new int[RIDE_SEEN_N];
    static readonly int[] rideSeenFill = new int[RIDE_SEEN_N];
    static ulong rideGen = 0;

    static bool RideGate(JsonElement p)
    {
        if (GetInt(p, "timed", 0) != 0) return false;
        if (GetInt(p, "no_output", 0) != 0) return false;
        if (GetInt(p, "use_float", 0) != 0) return false;
        if (GetInt(p, "bench_mode", 0) != 0) return false;
        return GetInt(p, "iters", 1) <= 1;
    }

    /* 0 means the call returned. Anything else is the code C would have
     * returned for the same condition, so the three entry points are comparable
     * without narrowing the catch types; -1 is an exception the library does
     * not own, which is itself a divergence. */
    static int RideCode(Exception e) => e is ITALibFailure f ? (int) f.RetCode : -1;

    static bool RideFinite(double[] a, int n)
    {
        for (int i = 0; i < n; i++) if (!double.IsFinite(a[i])) return false;
        return true;
    }

    static ulong RideMix(ulong h, ulong v)
    {
        ulong acc = h;
        for (int i = 0; i < 8; i++)
        {
            acc ^= (v >> (i * 8)) & 0xffUL;
            acc *= 1099511628211UL;
        }
        return acc;
    }

    static ulong RideMixStr(ulong h, string s)
    {
        ulong acc = h;
        for (int i = 0; i < s.Length; i++)
        {
            acc ^= (ulong)(s[i] & 0xff);
            acc *= 1099511628211UL;
        }
        return acc;
    }

    static ulong RideMixArr(ulong h, double[] a, int n)
    {
        ulong acc = h;
        for (int i = 0; i < n; i++) acc = RideMix(acc, (ulong)BitConverter.DoubleToInt64Bits(a[i]));
        return acc;
    }

    sealed class RideResult
    {
        public bool Ok = true;
        public int Skip, Dedup, OpenBars, FillBars, Leg, Bar = -1, Out = -1, M, Lb = -1;
        public int Rej, RcBatch, RcOpen, RcFill;
        public long Batch, Stream;
        public long[] Benign = new long[1];
        public void Emit(System.Text.StringBuilder sb)
        {
            sb.Append($",\"ride_ok\":{(Ok ? 1 : 0)},\"ride_skip\":{Skip},\"ride_dedup\":{Dedup}");
            sb.Append($",\"ride_open_bars\":{OpenBars},\"ride_fill_bars\":{FillBars}");
            sb.Append($",\"ride_benign\":{Benign[0]},\"ride_m\":{M},\"ride_lb\":{Lb}");
            sb.Append($",\"ride_rej\":{Rej},\"ride_rc_batch\":{RcBatch}");
            sb.Append($",\"ride_rc_open\":{RcOpen},\"ride_rc_fill\":{RcFill}");
            if (!Ok)
            {
                sb.Append($",\"ride_leg\":{Leg},\"ride_bar\":{Bar},\"ride_out\":{Out}");
                sb.Append($",\"ride_batch\":\"{Batch:x16}\",\"ride_stream\":\"{Stream:x16}\"");
            }
        }
    }

    static void RideAc(Core core, JsonElement p, int endIdx, double[] inHigh, double[] inLow, int optInFastPeriod, int optInSlowPeriod, int optInSignalPeriod, System.Text.StringBuilder sb)
    {
        if (!RideGate(p)) return;
        RideResult r = new RideResult();
        RideBodyAc(core, p, endIdx, inHigh, inLow, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, r);
        r.Emit(sb);
    }

    static void RideBodyAc(Core core, JsonElement p, int endIdx, double[] inHigh, double[] inLow, int optInFastPeriod, int optInSlowPeriod, int optInSignalPeriod, RideResult r)
    {
        try { r.Lb = core.AcLookback(optInFastPeriod, optInSlowPeriod, optInSignalPeriod); } catch (Exception) { r.Lb = -1; }
        int lb = r.Lb;
        int navail = endIdx + 1;
        if (inHigh.Length < navail) navail = inHigh.Length;
        if (inLow.Length < navail) navail = inLow.Length;
        int m = lb >= 0 ? 2 * lb + 10 : navail;
        if (m > navail) m = navail;
        r.M = m;
        if (m > RIDE_MAX_BARS) { r.Skip = 1; return; }
        if (m < 1) { r.Skip = 2; return; }
        if (lb >= 0 && m < lb + 2) { r.Skip = 3; return; }
        if (!RideFinite(inHigh, m) || !RideFinite(inLow, m) || false) { r.Skip = 4; return; }

        ulong hash = 0xcbf29ce484222325UL;
        hash = RideMixStr(hash, "TA_AC");
        hash = RideMix(hash, (ulong) m);
        hash = RideMix(hash, rideGen);
        hash = RideMix(hash, (ulong)(long) GetInt(p, "unstablePeriod", 0));
        hash = RideMix(hash, (ulong)(long) optInFastPeriod);
        hash = RideMix(hash, (ulong)(long) optInSlowPeriod);
        hash = RideMix(hash, (ulong)(long) optInSignalPeriod);
        hash = RideMixArr(hash, inHigh, m);
        hash = RideMixArr(hash, inLow, m);
        int slot = (int)(hash % (ulong) RIDE_SEEN_N);
        if (rideSeenUsed[slot] && rideSeenHash[slot] == hash)
        {
            r.Dedup = 1; r.OpenBars = rideSeenOpen[slot]; r.FillBars = rideSeenFill[slot]; return;
        }

        double[] rb0 = new double[m];
        int beg = 0;
        int nb = 0;
        string clsB = "";
        bool rejected = false;
        try { OutRange _rr = core.Ac(0, m - 1, inHigh.AsSpan(0, m), inLow.AsSpan(0, m), optInFastPeriod, optInSlowPeriod, optInSignalPeriod, rb0); beg = _rr.BegIdx; nb = _rr.Count; }
        catch (Exception _e) { r.RcBatch = RideCode(_e); clsB = _e.GetType().FullName ?? ""; rejected = true; }
        if (rejected)
        {
            string clsO = "", clsF = "";
            try { core.AcOpen(inHigh.AsSpan(0, m), inLow.AsSpan(0, m), optInFastPeriod, optInSlowPeriod, optInSignalPeriod); } catch (Exception _e) { r.RcOpen = RideCode(_e); clsO = _e.GetType().FullName ?? ""; }
            double[] fb0 = new double[m];
            try { core.AcOpenAndFill(inHigh.AsSpan(0, m), inLow.AsSpan(0, m), optInFastPeriod, optInSlowPeriod, optInSignalPeriod, fb0); } catch (Exception _e) { r.RcFill = RideCode(_e); clsF = _e.GetType().FullName ?? ""; }
            bool cmpO = r.RcOpen == r.RcBatch && clsO == clsB;
            if (cmpO) r.Rej++;
            if (!cmpO) { r.Ok = false; r.Leg = r.RcOpen == r.RcBatch ? 4 : 3; }
            bool cmpF = r.RcFill == r.RcBatch && clsF == clsB;
            if (cmpF) r.Rej++;
            if (!cmpF) { r.Ok = false; r.Leg = r.RcFill == r.RcBatch ? 4 : 3; }
            return;
        }
        if (lb < 0) { r.Skip = 7; return; }
        if (nb == 0) { r.Skip = 5; return; }
        if (beg != lb) { r.Skip = 6; return; }

        try
        {
            bool cmp;
            var st = core.AcOpen(inHigh.AsSpan(0, lb + 1), inLow.AsSpan(0, lb + 1), optInFastPeriod, optInSlowPeriod, optInSignalPeriod);
            var uv = st.Value;
            cmp = true;
            if (cmp && SvXtierNe(rb0[lb - beg], uv, ref r.Benign[0])) { cmp = false; r.Out = 0; r.Batch = BitConverter.DoubleToInt64Bits(rb0[lb - beg]); r.Stream = BitConverter.DoubleToInt64Bits(uv); }
            if (cmp) r.OpenBars++;
            if (!cmp) { r.Ok = false; r.Leg = 1; r.Bar = lb; }
            for (int t = lb + 1; r.Ok && t < m; t++)
            {
                uv = st.Update(inHigh[t], inLow[t]);
                cmp = true;
                if (cmp && SvXtierNe(rb0[t - beg], uv, ref r.Benign[0])) { cmp = false; r.Out = 0; r.Batch = BitConverter.DoubleToInt64Bits(rb0[t - beg]); r.Stream = BitConverter.DoubleToInt64Bits(uv); }
                if (cmp) r.OpenBars++;
                if (!cmp) { r.Ok = false; r.Leg = 1; r.Bar = t; }
            }
        }
        catch (Exception) { r.Ok = false; r.Leg = 1; }

        if (r.Ok)
        {
            double[] fb0 = new double[m];
            try
            {
                var st2 = core.AcOpenAndFill(inHigh.AsSpan(0, m), inLow.AsSpan(0, m), optInFastPeriod, optInSlowPeriod, optInSignalPeriod, fb0);
                if (st2.OutRange.BegIdx != beg || st2.OutRange.Count != nb) { r.Ok = false; r.Leg = 2; }
                if (r.Ok)
                {
                    for (int k = 0; k < nb; k++)
                    {
                        bool cmp = true;
                        if (cmp && SvXtierNe(rb0[k], fb0[k], ref r.Benign[0])) { cmp = false; r.Out = 0; r.Batch = BitConverter.DoubleToInt64Bits(rb0[k]); r.Stream = BitConverter.DoubleToInt64Bits(fb0[k]); }
                        if (cmp) r.FillBars++;
                        if (!cmp) { r.Ok = false; r.Leg = 2; r.Bar = beg + k; break; }
                    }
                }
            }
            catch (Exception) { r.Ok = false; r.Leg = 2; }
        }

        if (r.Ok)
        {
            rideSeenUsed[slot] = true; rideSeenHash[slot] = hash;
            rideSeenOpen[slot] = r.OpenBars; rideSeenFill[slot] = r.FillBars;
        }
    }

